# Diagnose before repair; preserve available snapshot; never claim the overwritten first ZIP was saved.
import base64, hashlib, importlib.util, json, zlib
from pathlib import Path
app=Path('/kaggle/working/care-assistant-pilot/care-assistant')
assert app.is_dir() and Path('/kaggle/working').is_dir()
runner=app/'finetuning/kaggle/runner.py'
source=runner.read_text(); current=hashlib.sha256(source.encode()).hexdigest()
assert current in ['c645953b5dfd286676070fe9cdaa159407c371aec838765add4170cb0a518d11', 'b7974f03d4653fd2722216f97671d92f855ea5a48759cc096fd6ded33d97c5af'], 'Unexpected runner edits; stop and inspect'
helper_source=zlib.decompress(base64.b64decode(''))
assert hashlib.sha256(helper_source).hexdigest()=='f07a2fd1ad521462ff13e67aded3a183dbc908d792be6644957f4f0e7e168458'
pins={'uv': {'version': '0.13.8', 'filename': 'uv-0.13.8-py3-none-manylinux_2_17_x86_64.manylinux2014_x86_64.whl', 'url': 'https://files.pythonhosted.org/packages/c5/32/52ee34636aea1ab3f8baeeae1c3599461b8cddfb379862cc72ac61b8d91c/uv-0.13.8-py3-none-manylinux_2_17_x86_64.manylinux2014_x86_64.whl', 'sha256': 'e18a57b8b352eb7c8feb317b9f6f533c8f0ad9673fd6cf34bbe3cf1a9f6a8984', 'source': 'https://pypi.org/pypi/uv/0.13.8/json', 'requires_python': '>=3.8'}, 'pip': {'version': '26.3', 'filename': 'pip-26.3-py3-none-any.whl', 'url': 'https://files.pythonhosted.org/packages/07/25/ee8c38ae72d66b844ce8eb9711ba905dba21ca1a8a0c960057c41cd23337/pip-26.3-py3-none-any.whl', 'sha256': 'f3b60b20ffaadd4415ed7957212a38ac63fa4c5fa375bd0f4a797777940fad13', 'source': 'https://pypi.org/pypi/pip/26.3/json', 'requires_python': '>=3.10'}}
helper=app/'finetuning/kaggle/bootstrap_env.py'; helper.write_bytes(helper_source)
(app/'finetuning/config/bootstrap-pins.json').write_text(json.dumps(pins,indent=2)+'\n')
spec=importlib.util.spec_from_file_location('care_bootstrap_repair',helper)
repair=importlib.util.module_from_spec(spec); spec.loader.exec_module(repair)
repair.ensure_environment(Path('/tmp/chest-bpm-e4b-pilot'),app/'finetuning/runs',pins,force_diagnostics=True)
if current=='c645953b5dfd286676070fe9cdaa159407c371aec838765add4170cb0a518d11':
    source=source.replace(" if not PYTHON.exists():venv.EnvBuilder(with_pip=True).create(SCRATCH/'venv')"," from bootstrap_env import ensure_environment\n ensure_environment(SCRATCH, ARTIFACTS, json.loads((FT/'config/bootstrap-pins.json').read_text()), ENV)")
    runner.write_text(source)
assert hashlib.sha256(runner.read_bytes()).hexdigest()=='b7974f03d4653fd2722216f97671d92f855ea5a48759cc096fd6ded33d97c5af'
print('Bootstrap-only patch verified; resuming the original pinned setup.')
# Do NOT rerun the old embedded-bundle extraction: it would restore the old runner.
stage('setup')
